function d_artifact_gen(P,R){var secs=P.sections||['overview','design','tests','plan'];var doc={title:P.title||'artifact',sections:[]};var words=0;secs.forEach(function(s){var w=80+Math.floor(R()*120);words+=w;doc.sections.push({name:s,words:w});});doc.total_words=words;doc.traceable=true;return doc;}

