function d_lint_check(P,R){var code=P.code||'';var issues=[];if(/eval\(/.test(code))issues.push({rule:'no-eval',severity:'error'});if(/var\s/.test(code))issues.push({rule:'prefer-const',severity:'warning'});if(code.indexOf('TODO')>=0)issues.push({rule:'no-todo',severity:'info'});var lines=code.split('\n').length;return{lines:lines,issues:issues,clean:issues.filter(function(i){return i.severity==='error';}).length===0};}

